ALTER TYPE "UserRole" ADD VALUE IF NOT EXISTS 'REVIEWER';
CREATE TYPE "TemplateVisibility" AS ENUM ('PRIVATE','UNLISTED','PUBLIC');
CREATE TYPE "TemplateReviewStatus" AS ENUM ('DRAFT','PENDING','APPROVED','REJECTED');
CREATE TYPE "TemplateLifecycleStatus" AS ENUM ('ACTIVE','ARCHIVED');
CREATE TYPE "TemplateReviewAction" AS ENUM ('SUBMITTED','APPROVED','REJECTED','CHANGES_REQUESTED','UNPUBLISHED');
CREATE TYPE "TemplateMetricType" AS ENUM ('DOWNLOAD','VIEW','INSTALL');
CREATE TABLE "TemplateCategory" ("id" UUID NOT NULL,"slug" VARCHAR(100) NOT NULL,"name" VARCHAR(100) NOT NULL,"description" VARCHAR(500),"sortOrder" INTEGER NOT NULL DEFAULT 0,"isActive" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "TemplateCategory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Template" ("id" UUID NOT NULL,"slug" VARCHAR(100) NOT NULL,"ownerId" UUID NOT NULL,"title" VARCHAR(150) NOT NULL,"description" VARCHAR(2000),"visibility" "TemplateVisibility" NOT NULL DEFAULT 'PRIVATE',"reviewStatus" "TemplateReviewStatus" NOT NULL DEFAULT 'DRAFT',"lifecycleStatus" "TemplateLifecycleStatus" NOT NULL DEFAULT 'ACTIVE',"currentVersionId" UUID,"categoryId" UUID,"tags" TEXT[] DEFAULT ARRAY[]::TEXT[],"rejectionReason" VARCHAR(1000),"submittedAt" TIMESTAMP(3),"approvedAt" TIMESTAMP(3),"publishedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"deletedAt" TIMESTAMP(3),CONSTRAINT "Template_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TemplateVersion" ("id" UUID NOT NULL,"templateId" UUID NOT NULL,"versionNumber" INTEGER NOT NULL,"changelog" VARCHAR(1000),"libraryType" VARCHAR(100) NOT NULL,"librarySchemaVersion" INTEGER NOT NULL DEFAULT 2,"source" VARCHAR(500) NOT NULL,"itemCount" INTEGER NOT NULL,"manifestStorageKey" VARCHAR(500) NOT NULL,"bundleStorageKey" VARCHAR(500),"previewStorageKey" VARCHAR(500),"contentHash" VARCHAR(64) NOT NULL,"bundleSize" INTEGER,"createdById" UUID NOT NULL,"immutable" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TemplateVersion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TemplateItem" ("id" UUID NOT NULL,"templateVersionId" UUID NOT NULL,"externalId" VARCHAR(150) NOT NULL,"name" VARCHAR(150),"description" VARCHAR(1000),"category" VARCHAR(100),"form" VARCHAR(100),"sortOrder" INTEGER NOT NULL,"elementsJson" JSONB NOT NULL,"previewStorageKey" VARCHAR(500),"contentHash" VARCHAR(64) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TemplateItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TemplateReview" ("id" UUID NOT NULL,"templateId" UUID NOT NULL,"reviewerId" UUID,"action" "TemplateReviewAction" NOT NULL,"comment" VARCHAR(1000),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TemplateReview_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TemplateShare" ("id" UUID NOT NULL,"templateId" UUID NOT NULL,"tokenHash" VARCHAR(64) NOT NULL,"expiresAt" TIMESTAMP(3),"maxUses" INTEGER,"useCount" INTEGER NOT NULL DEFAULT 0,"revokedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TemplateShare_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TemplateMetric" ("id" UUID NOT NULL,"templateId" UUID NOT NULL,"userId" UUID,"type" "TemplateMetricType" NOT NULL,"visitorHash" VARCHAR(64),"dedupeKey" VARCHAR(64) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TemplateMetric_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "TemplateCategory_slug_key" ON "TemplateCategory"("slug"); CREATE INDEX "TemplateCategory_isActive_sortOrder_idx" ON "TemplateCategory"("isActive","sortOrder");
CREATE UNIQUE INDEX "Template_slug_key" ON "Template"("slug"); CREATE UNIQUE INDEX "Template_currentVersionId_key" ON "Template"("currentVersionId"); CREATE INDEX "Template_ownerId_deletedAt_updatedAt_idx" ON "Template"("ownerId","deletedAt","updatedAt"); CREATE INDEX "Template_visibility_reviewStatus_lifecycleStatus_publishedAt_idx" ON "Template"("visibility","reviewStatus","lifecycleStatus","publishedAt"); CREATE INDEX "Template_categoryId_publishedAt_idx" ON "Template"("categoryId","publishedAt");
CREATE UNIQUE INDEX "TemplateVersion_templateId_versionNumber_key" ON "TemplateVersion"("templateId","versionNumber"); CREATE INDEX "TemplateVersion_templateId_createdAt_idx" ON "TemplateVersion"("templateId","createdAt"); CREATE INDEX "TemplateVersion_contentHash_idx" ON "TemplateVersion"("contentHash");
CREATE UNIQUE INDEX "TemplateItem_templateVersionId_externalId_key" ON "TemplateItem"("templateVersionId","externalId"); CREATE INDEX "TemplateItem_category_form_idx" ON "TemplateItem"("category","form"); CREATE INDEX "TemplateReview_templateId_createdAt_idx" ON "TemplateReview"("templateId","createdAt");
CREATE UNIQUE INDEX "TemplateShare_tokenHash_key" ON "TemplateShare"("tokenHash"); CREATE INDEX "TemplateShare_templateId_revokedAt_idx" ON "TemplateShare"("templateId","revokedAt"); CREATE UNIQUE INDEX "TemplateMetric_dedupeKey_key" ON "TemplateMetric"("dedupeKey"); CREATE INDEX "TemplateMetric_templateId_type_createdAt_idx" ON "TemplateMetric"("templateId","type","createdAt");
ALTER TABLE "Template" ADD CONSTRAINT "Template_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Template" ADD CONSTRAINT "Template_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "TemplateCategory"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "Template" ADD CONSTRAINT "Template_currentVersionId_fkey" FOREIGN KEY ("currentVersionId") REFERENCES "TemplateVersion"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "TemplateVersion" ADD CONSTRAINT "TemplateVersion_templateId_fkey" FOREIGN KEY ("templateId") REFERENCES "Template"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "TemplateVersion" ADD CONSTRAINT "TemplateVersion_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "TemplateItem" ADD CONSTRAINT "TemplateItem_templateVersionId_fkey" FOREIGN KEY ("templateVersionId") REFERENCES "TemplateVersion"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "TemplateReview" ADD CONSTRAINT "TemplateReview_templateId_fkey" FOREIGN KEY ("templateId") REFERENCES "Template"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "TemplateReview" ADD CONSTRAINT "TemplateReview_reviewerId_fkey" FOREIGN KEY ("reviewerId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "TemplateShare" ADD CONSTRAINT "TemplateShare_templateId_fkey" FOREIGN KEY ("templateId") REFERENCES "Template"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "TemplateMetric" ADD CONSTRAINT "TemplateMetric_templateId_fkey" FOREIGN KEY ("templateId") REFERENCES "Template"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "TemplateMetric" ADD CONSTRAINT "TemplateMetric_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
